    ml: "ക്രെഡിറ്റ് വിലയിരുത്തലിനും പരിശോധനയ്ക്കുമായി എന്റെ വിവരങ്ങൾ അധികൃത മൂന്നാം കക്ഷികളുമായും ക്രെഡിറ്റ് ബ്യൂറോകളുമായും ഉപയോഗിക്കാനും പങ്കിടാനും ഞാൻ സമ്മതിക്കുന്നു.",
    ta: "கடன் மதிப்பீடு மற்றும் சரிபார்ப்புக்காக எனது தகவலை அதிகாரம் பெற்ற மூன்றாம் தரப்பினர் மற்றும் கடன் பணியகங்களுடன் பயன்படுத்தவும் பங்கிடவும் நான் சம்மதிக்கிறேன்.",
    te: "క్రెడిట్ అంచనా మరియు ధృవీకరణ కోసం నా సమాచారాన్ని అధీకృత థర్డ్ పార్టీలు మరియు క్రెడిట్ బ్యూరోలతో ఉపయోగించడానికి, షేర్ చేయడానికి నేను సమ్మతిస్తున్నాను.",
    kn: "ಕ್ರೆಡಿಟ್ ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಪರಿಶೀಲನೆಗಾಗಿ ನನ್ನ ಮಾಹಿತಿಯನ್ನು ಅಧಿಕೃತ ಮೂರನೇ ಪಕ್ಷಗಳು ಮತ್ತು ಕ್ರೆಡಿಟ್ ಬ್ಯೂರೋಗಳೊಂದಿಗೆ ಬಳಸಲು ಮತ್ತು ಹಂಚಿಕೊಳ್ಳಲು ನಾನು ಸಮ್ಮತಿ ನೀಡುತ್ತೇನೆ.",
    hi: "मैं क्रेडिट आंकलन और सत्यापन के लिए अपनी जानकारी अधिकृत तीसरे पक्षों और क्रेडिट ब्यूरो के साथ उपयोग व साझा करने की सहमति देता हूं।",
