  changePickupHint: {
    ne: "तपाईं आफ्नो पिक-अप मिति एक पटक, 3 दिनसम्म सार्न सक्नुहुन्छ।",
    "or": "ଆପଣ ଆପଣଙ୍କ ପିକ୍-ଅପ୍ ତାରିଖକୁ ଥରେ, 3 ଦିନ ପରେ ପର୍ଯ୍ୟନ୍ତ ବଦଳାଇ ପାରିବେ।",
    ml: "നിങ്ങളുടെ പിക്ക്-അപ്പ് തീയതി ഒരു പ്രാവശ്യം, 3 ദിവസം വരെ മാറ്റാം.",
    ta: "உங்கள் பிக்-அப் தேதியை ஒருமுறை, 3 நாட்கள் வரை மாற்றலாம்.",
    te: "మీ పికప్ తేదీని ఒక్కసారి, 3 రోజుల వరకు మార్చవచ్చు.",
    kn: "ನಿಮ್ಮ ಪಿಕ್-ಅಪ್ ದಿನಾಂಕವನ್ನು ಒಮ್ಮೆ, 3 ದಿನಗಳವರೆಗೆ ಮುಂದೂಡಬಹುದು.",
    hi: "आप अपनी पिक-अप तारीख एक बार, 3 दिन बाद तक बदल सकते हैं।", en: "You can move your pick-up date once, up to 3 days later." },
  changePickupUsed: {
    ne: "पिक-अपको मिति एक पटक परिवर्तन भइसकेको छ। यदि थप समय चाहियो भने हबमा कल गर्नुहोस्।",
    "or": "ପିକ୍-ଅପ୍ ତାରିଖ ପୂର୍ବରୁ ଥରେ ବଦଳାଯାଇଛି। ଯଦି ଆପଣଙ୍କୁ ଅଧିକ ସମୟ ଦରକାର, ହବ୍‌କୁ ଫୋନ୍ କରନ୍ତୁ।",
    ml: "പിക്ക്-അപ്പ് തീയതി ഒരുതവണ മാറ്റിയിട്ടുണ്ട്. കൂടുതൽ സമയം വേണമെങ്കിൽ ഹബുമായി ബന്ധപ്പെടുക.",
    ta: "பிக்கப் தேதியை ஏற்கெனவே ஒருமுறை மாற்றிவிட்டீர்கள். மேலும் நேரம் தேவைப்பட்டால், ஹப்புக்கு கால் செய்யுங்கள்.",
    te: "పికప్ తేదీని ఇప్పటికే ఒకసారి మార్చారు. మీకు ఇంకా సమయం కావాలంటే హబ్‌కి కాల్ చేయండి.",
    kn: "ಪಿಕಪ್ ದಿನಾಂಕವನ್ನು ಈಗಾಗಲೇ ಒಮ್ಮೆ ಬದಲಾಯಿಸಲಾಗಿದೆ. ನಿಮಗೆ ಹೆಚ್ಚು ಸಮಯ ಬೇಕಿದ್ದರೆ ಹಬ್‌ಗೆ ಕರೆ ಮಾಡಿ.",
    hi: "पिक-अप की तारीख एक बार बदल चुकी है। अगर और समय चाहिए तो हब पर कॉल करें।", en: "Pick-up date already changed once. Call the hub if you need more time." },
  changePickupDone: {
    ne: "पिक-अपको मिति अपडेट भयो।",
    "or": "ପିକ୍-ଅପ୍ ତାରିଖ ଅପଡେଟ୍ ହୋଇଗଲା।",
    ml: "പിക്ക്-അപ്പ് തീയതി അപ്‌ഡേറ്റ് ചെയ്തു.",
    ta: "பிக்கப் தேதி அப்டேட் செய்யப்பட்டுள்ளது.",
    te: "పికప్ తేదీ అప్‌డేట్ చేయబడింది.",
    kn: "ಪಿಕಪ್ ದಿನಾಂಕ ನವೀಕರಿಸಲಾಗಿದೆ.",
    hi: "पिक-अप की तारीख अपडेट हो गई है।", en: "Pick-up date updated." },
  changePickupTooFar: {
    ne: "नयाँ मिति तपाईंको मौलिक पिक-अप मितिको 3 दिनपछि सम्म मात्र हुन सक्छ।",
    "or": "ନୂଆ ତାରିଖ ଆପଣଙ୍କର ମୂଳ ପିକ୍-ଅପ୍ ତାରିଖର 3 ଦିନ ପରେ ପର୍ଯ୍ୟନ୍ତ ହୋଇପାରିବ।",
    ml: "പുതിയ തീയതി നിങ്ങളുടെ യഥാർത്ഥ പിക്ക്-അപ്പ് തീയതിക്ക് ശേഷം 3 ദിവസം വരെയാകാം.",
    ta: "புதிய தேதி உங்கள் அசல் பிக்கப் தேதிக்குப் பிறகு 3 நாட்கள் வரை மட்டுமே இருக்கலாம்.",
    te: "కొత్త తేదీ మీ ఒరిజినల్ పికప్ తేదీ తర్వాత 3 రోజుల వరకు ఉండవచ్చు.",
    kn: "ಹೊಸ ದಿನಾಂಕ ನಿಮ್ಮ ಮೂಲ ಪಿಕಪ್ ದಿನಾಂಕದ 3 ದಿನಗಳ ನಂತರದವರೆಗೆ ಮಾತ್ರ ಇರಬಹುದು.",
    hi: "नई तारीख आपके ओरिजिनल पिक-अप तारीख के 3 दिन बाद तक ही हो सकती है।", en: "New date can be up to 3 days after your original pick-up date." },
